// rationale:
// - use the event's own popup reminder offsets (Google sends them only when
//   reminders.useDefault === false, otherwise the reminder list is implicit)
// - a reminder is "due" at eventStart - M minutes; because this workflow runs
//   once per minute, we accept a +/- window (due-15s .. due+75s) so exactly one
//   poll matches each reminder
// - workflow static data ('global') keeps a `voiced` map keyed by
//   `${id}|${startISO}|${M}` for dedup; keys are pruned after 48h
// - a key is only recorded AFTER a successful announcement (done in the
//   "Mark Announced" node), so a failed TTS call can retry on the next poll

const staticData = $getWorkflowStaticData('global');
if (!staticData.voiced) {
  staticData.voiced = {};
}
const voiced = staticData.voiced;

// prune entries older than 48 hours (values are announce timestamps in ms)
const PRUNE_MS = 48 * 60 * 60 * 1000;
const nowMs = Date.now();
for (const key of Object.keys(voiced)) {
  if (nowMs - voiced[key] > PRUNE_MS) {
    delete voiced[key];
  }
}

function plural(n, one, few, many) {
  const mod10 = n % 10;
  const mod100 = n % 100;
  if (mod10 === 1 && mod100 !== 11) return one;
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return few;
  return many;
}

function formatOffset(minutes) {
  // Russian plural forms: 1 минута, 2-4 минуты, 5-20 минут;
  // >= 60 minutes wraps to hours, >= 1440 to days (with remainder).
  minutes = Math.round(minutes);
  if (minutes <= 0) return 'менее минуты';
  if (minutes < 60) {
    return `${minutes} ${plural(minutes, 'минуту', 'минуты', 'минут')}`;
  }
  const days = Math.floor(minutes / 1440);
  const hours = Math.floor((minutes % 1440) / 60);
  const mins = minutes % 60;
  const parts = [];
  if (days) parts.push(`${days} ${plural(days, 'день', 'дня', 'дней')}`);
  if (hours) parts.push(`${hours} ${plural(hours, 'час', 'часа', 'часов')}`);
  if (mins) parts.push(`${mins} ${plural(mins, 'минуту', 'минуты', 'минут')}`);
  return parts.join(' ');
}

const WINDOW_BEFORE_MS = 15 * 1000;
const WINDOW_AFTER_MS = 75 * 1000;

const out = [];
for (const item of items) {
  const event = item.json;

  // only events with explicit (non-default) reminders carry an overrides array
  const hasExplicitReminders =
    event.reminders &&
    event.reminders.useDefault === false &&
    Array.isArray(event.reminders.overrides);
  if (!hasExplicitReminders) continue;

  // all-day events have start.date (YYYY-MM-DD) -> treat as local midnight
  let startISO;
  if (event.start && event.start.dateTime) {
    startISO = event.start.dateTime;
  } else if (event.start && event.start.date) {
    startISO = `${event.start.date}T00:00:00`;
  } else {
    continue;
  }
  const startMs = Date.parse(startISO);
  if (Number.isNaN(startMs)) continue;

  for (const override of event.reminders.overrides) {
    if (override.method !== 'popup') continue;
    const M = Number(override.minutes);
    const dueMs = startMs - M * 60 * 1000;
    if (nowMs < dueMs - WINDOW_BEFORE_MS || nowMs > dueMs + WINDOW_AFTER_MS) continue;

    const key = `${event.id}|${startISO}|${M}`;
    if (voiced[key]) continue;

    const summary = (event.summary || 'Событие').trim();
    const location = (event.location || '').trim();
    let text = `Через ${formatOffset(M)} начинается «${summary}»`;
    if (location) text += `. Место: ${location}`;
    text += '.';

    out.push({ json: { text, dedupKey: key } });
  }
}

return out;

const data = $getWorkflowStaticData('global');
data.voiced ??= {};
for (let i = 0; i < items.length; i++) {
  if (items[i].json.status !== 'ok') throw new Error('Yandex announcement was not accepted');
  const source = $('Match Due Reminders').itemMatching(i).json;
  if (source.dedupKey) data.voiced[source.dedupKey] = Date.now();
}
return items;
